-- Official Cat Parts Store C15 / 3406 / 3408 service and reman references.
-- Reference-only: prices, stock and serial-level fitment are deliberately not inferred.
insert into public.part_catalog
  (part_number,name,description,engine_models,technical_group,source_name,source_url,source_note,verification_status,application_type,application_evidence,application_source_url,compatible_models)
values
('10R-1503','کیت سیلندر بازسازی‌شده Cat Reman 10R-1503','Cat Reman cylinder pack for C15 with 16.6:1 compression ratio. Cat describes a preassembled overhaul unit including liner, piston, rings, pin, retainers, connecting rod and seals.','{C15}','موتور - تعمیر اساسی - کیت سیلندر','Cat Parts Store (official)','https://parts.cat.com/en/catcorp/product/10R-1503','Official Cat product page identifies Cat Reman Cylinder Pack (C15), compression ratio 16.6:1, and lists Truck Engine C-15 plus recommended application C15. No customer price is public without dealer sign-in. Verify engine serial and arrangement.','REFERENCE','LAND','Cat Compatible Models lists TRUCK ENGINE C-15; Recommended Application is C15. No marine equipment class is listed on the retrieved page.','https://parts.cat.com/en/catcorp/product/10R-1503',array['C-15','C15']),
('0R-9942','کیت سیلندر بازسازی‌شده Cat Reman 0R-9942','Cat Reman C15 cylinder pack, low horsepower, 18:1 compression ratio. Official page describes the assembly as a preassembled overhaul option with liner, piston, rings, pin, retainers, connecting rod and seals.','{C15}','موتور - تعمیر اساسی - کیت سیلندر','Cat Parts Store (official)','https://parts.cat.com/en/catcorp/product/0R-9942','Official Cat Parts Store page identifies Cat C15 Reman Cylinder Pack (LOW HP), 18:1 compression ratio, and lists TRUCK ENGINE C-15. Page includes Cat product imagery; this reference row does not assert image or current stock. Verify serial and arrangement.','REFERENCE','LAND','Cat Compatible Models lists TRUCK ENGINE C-15. No marine equipment class is listed on the retrieved page.','https://parts.cat.com/en/catcorp/product/0R-9942',array['C-15','C15']),
('328-5573','یاتاقان شاتون Cat 328-5573','Cat connecting rod bearing; official description states it provides the conformable surface for the connecting rod to rotate on the crankshaft. Material: steel-backed copper-lead bearing.','{C15,3406B,3406C,3406E,3408}','موتور - بلوک و یاتاقان - یاتاقان شاتون','Cat Parts Store (official)','https://parts.cat.com/en/catcorp/product/328-5573','Official Cat product page lists dimensions and material and Compatible Models including Truck Engine C-15/C16, Marine Engine C15 and 3406B/C/E, plus multiple land equipment classes. Do not treat family listing as serial-specific fitment.','REFERENCE','BOTH','Cat Compatible Models explicitly includes Marine Engine C15/3406B/3406C/3406E and non-marine truck, industrial, generator and off-highway equipment classes.','https://parts.cat.com/en/catcorp/product/328-5573',array['C15','C-15','3406B','3406C','3406E','3408']),
('277-3076','لوله پاشش روغن پیستون Cat 277-3076','Cat oil jet brazed tube; official description states oil jet tubes distribute oil to the underside of piston domes to remove heat. Material: carbon steel and alloy copper.','{C15,3406E,3406C,3406B,3408}','موتور - روغن‌کاری - لوله پاشش روغن پیستون','Cat Parts Store (official)','https://parts.cat.com/en/catcorp/product/277-3076','Official Cat product page provides material, dimensions and Compatible Models including Truck Engine C-15/3406E/3406C/3406B, Marine Engine C15/3406E and multiple land equipment classes.','REFERENCE','BOTH','Cat Compatible Models explicitly includes Marine Engine C15 and 3406E plus non-marine truck, industrial, generator and off-highway equipment classes.','https://parts.cat.com/en/catcorp/product/277-3076',array['C15','C-15','3406B','3406C','3406E','3408']),
('0R-9449','پمپ روغن موتور بازسازی‌شده Cat Reman 0R-9449','Cat Reman 3406E one-section engine oil pump. Official Cat description explains that the pump circulates engine oil for lubrication and cooling.','{C15,C18,3406B,3406C,3406E,3408B,3408C,3412}','موتور - روغن‌کاری - پمپ روغن','Cat Parts Store (official)','https://parts.cat.com/en/catcorp/product/0R-9449','Official Cat Parts Store product page identifies Cat 3406E Reman Engine Oil Pump (One Section), provides dimensions and lists C15/C18/3406/3408 families in multiple marine and land compatible-model classes. Dealer pricing is not public.','REFERENCE','BOTH','Cat Compatible Models includes Marine Engine C18/C15/3408B/3408C/3406B/3406C/3406E and multiple land classes including Truck Engine, Industrial Engine, Generator Set and Off Highway Truck.','https://parts.cat.com/en/catcorp/product/0R-9449',array['C15','C18','3406B','3406C','3406E','3408B','3408C','3412'])
on conflict (part_number) do update set
 name=excluded.name,description=excluded.description,engine_models=excluded.engine_models,
 technical_group=excluded.technical_group,source_name=excluded.source_name,
 source_url=excluded.source_url,source_note=excluded.source_note,
 verification_status='REFERENCE',application_type=excluded.application_type,
 application_evidence=excluded.application_evidence,
 application_source_url=excluded.application_source_url,
 compatible_models=excluded.compatible_models,updated_at=now();
